1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import { and, eq } from "drizzle-orm";
4	import { inboxDismissals, joinRequests } from "@paperclipai/db";
5	import { sidebarBadgeService } from "../services/sidebar-badges.js";
6	import { accessService } from "../services/access.js";
7	import { dashboardService } from "../services/dashboard.js";
8	import { collapseDuplicatePendingHumanJoinRequests } from "../lib/join-request-dedupe.js";
9	import { forbidden, unauthorized } from "../errors.js";
10	import { expressHandler } from "../http/express-adapter.js";
11	import type { Handler, RequestCtx } from "../http/types.js";
12	import type { StorageService } from "../storage/types.js";
13	
14	function buildDismissedAtByKey(
15	  dismissals: Array<{ itemKey: string; dismissedAt: Date | string }>,
16	): Map<string, number> {
17	  return new Map(
18	    dismissals.map((dismissal) => [dismissal.itemKey, new Date(dismissal.dismissedAt).getTime()]),
19	  );
20	}
21	
22	/** Minimal company access check using fields available on ActorContext. */
23	function assertCompanyAccessCtx(ctx: RequestCtx, companyId: string) {
24	  if (!ctx.actor) throw unauthorized();
25	  if (ctx.actor.type === "agent" && ctx.actor.companyId !== companyId) {
26	    throw forbidden("Agent key cannot access another company");
27	  }
28	  // Board actor company-list enforcement is handled by the Express auth
29	  // middleware before the Handler is reached.
30	  // TODO(cloudflare): re-enforce companyIds list in Workers auth layer.
31	}
32	
33	function buildHandlers(db: Db) {
34	  const svc = sidebarBadgeService(db);
35	  const access = accessService(db);
36	  const dashboard = dashboardService(db);
37	
38	  // server/src/routes/sidebar-badges.ts:25
39	  const getSidebarBadges: Handler = async (ctx) => {
40	    const companyId = ctx.param("companyId") ?? "";
41	    assertCompanyAccessCtx(ctx, companyId);
42	
43	    let canApproveJoins = false;
44	    if (ctx.actor?.type === "board") {
45	      // TODO(cloudflare): ctx.actor lacks `source` and `isInstanceAdmin`; the
46	      // local_implicit / isInstanceAdmin fast-path cannot be applied here.
47	      // Full permission check via access service is used for all board actors.
48	      canApproveJoins = await access.canUser(companyId, ctx.actor.userId, "joins:approve");
49	    } else if (ctx.actor?.type === "agent" && ctx.actor.agentId) {
50	      canApproveJoins = await access.hasPermission(companyId, "agent", ctx.actor.agentId, "joins:approve");
51	    }
52	
53	    const visibleJoinRequests = canApproveJoins
54	      ? collapseDuplicatePendingHumanJoinRequests(
55	        await db
56	          .select({
57	            id: joinRequests.id,
58	            requestType: joinRequests.requestType,
59	            status: joinRequests.status,
60	            requestingUserId: joinRequests.requestingUserId,
61	            requestEmailSnapshot: joinRequests.requestEmailSnapshot,
62	            updatedAt: joinRequests.updatedAt,
63	            createdAt: joinRequests.createdAt,
64	          })
65	          .from(joinRequests)
66	          .where(and(eq(joinRequests.companyId, companyId), eq(joinRequests.status, "pending_approval")))
67	      ).map(({ id, updatedAt, createdAt }) => ({
68	        id,
69	        updatedAt,
70	        createdAt,
71	      }))
72	      : [];
73	
74	    const dismissedAtByKey =
75	      ctx.actor?.type === "board" && ctx.actor.userId
76	        ? await db
77	          .select({ itemKey: inboxDismissals.itemKey, dismissedAt: inboxDismissals.dismissedAt })
78	          .from(inboxDismissals)
79	          .where(and(eq(inboxDismissals.companyId, companyId), eq(inboxDismissals.userId, ctx.actor.userId)))
80	          .then(buildDismissedAtByKey)
81	        : new Map<string, number>();
82	
83	    const badges = await svc.get(companyId, {
84	      dismissals: dismissedAtByKey,
85	      joinRequests: visibleJoinRequests,
86	    });
87	    const summary = await dashboard.summary(companyId);
88	    const hasFailedRuns = badges.failedRuns > 0;
89	    const alertsCount =
90	      (summary.agents.error > 0 && !hasFailedRuns ? 1 : 0) +
91	      (summary.costs.monthBudgetCents > 0 && summary.costs.monthUtilizationPercent >= 80 ? 1 : 0);
92	    badges.inbox = badges.failedRuns + alertsCount + badges.joinRequests + badges.approvals;
93	
94	    return Response.json(badges);
95	  };
96	
97	  return { getSidebarBadges };
98	}
99	
100	export function sidebarBadgeRoutes(db: Db) {
101	  const router = Router();
102	  const { getSidebarBadges } = buildHandlers(db);
103	
104	  const storageSentinel = new Proxy({} as StorageService, {
105	    get(_target, prop) {
106	      throw new Error(`sidebarBadge handler unexpectedly accessed storage.${String(prop)}`);
107	    },
108	  });
109	  const deps = { db, storage: storageSentinel };
110	
111	  router.get("/companies/:companyId/sidebar-badges", expressHandler(getSidebarBadges, deps));
112	
113	  return router;
114	}
